public interface IPricingStrategy { decimal Price(decimal qty); }   // Strategy

public sealed class WholesalePricing : IPricingStrategy              // carries state
{
    private readonly decimal _discount;
    public WholesalePricing(decimal discount) => _discount = discount;
    public decimal Price(decimal qty) => qty * (1 - _discount);
}

public sealed class Checkout                                          // Context
{
    private readonly IPricingStrategy _pricing;
    public Checkout(IPricingStrategy pricing) => _pricing = pricing;
    public decimal Total(decimal qty) => _pricing.Price(qty);
}
